def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    ax, ay = observation['self_position']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    opponent_pos = observation.get('opponent_position')
    remaining = observation.get('remaining_resource_count', 0)

    def move_towards(tx, ty):
        dx = (tx > ax) - (tx < ax)
        dy = (ty > ay) - (ty < ay)
        if (ax + dx, ay + dy) not in obstacles and 0 <= ax + dx < wx and 0 <= ay + dy < wy:
            return [dx, dy]
        # Try moving in x only
        if dx != 0 and (ax + dx, ay) not in obstacles and 0 <= ax + dx < wx:
            return [dx, 0]
        # Try moving in y only
        if dy != 0 and (ax, ay + dy) not in obstacles and 0 <= ay + dy < wy:
            return [0, dy]
        return [0, 0]

    if resources:
        nearest = min(resources, key=lambda r: abs(r[0]-ax)+abs(r[1]-ay))
        return move_towards(nearest[0], nearest[1])

    if opponent_pos:
        return move_towards(opponent_pos[0], opponent_pos[1])

    # Default: stay in place
    return [0, 0]
